head.script:
scwin.screenId = "jlddst10200";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_paxreq", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("paxreq")))); } },
        { childId: "ipt_outsvcno", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("outsvcno")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if ($c.util.getComponent('ipt_paxreq').getValue() === "y") {
            (console.error('[sdd] 이 화면 문서에 #titleValue 가 없다 — append() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#titleValue")).append("(PAXNET)");
        } else {
            if ($c.util.getComponent('ipt_outsvcno').getValue() === "02") {
                (console.error('[sdd] 이 화면 문서에 #titleValue 가 없다 — append() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#titleValue")).append("(헤럴드미디어)");
            }
        }
        $c.util.getComponent("tabContents").setStyle("display", "none");
        console.error("[sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
            await scwin.fnSearchCorpBasicInfo('');
        } else {
            await scwin.fnInitComNmSetting();
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst10200.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @description tab-contents 을(를) 보이기를 바꾼다 · 보이기를 바꾼다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst10200.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

